import{z as n,x as B,o as i,c as d,q as r,j as A,D as e,d as l,s,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"环形场","description":"","frontmatter":{"title":"环形场","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/ring-field.md","filePath":"litho/ring-field.md","lastUpdated":1791063341000}'),p={name:"litho/ring-field.md"};function h(D,a,m,f,F,u){const t=B("Mermaid");return i(),d("div",null,[a[2]||(a[2]=r('<h1 id="环形场" tabindex="-1">环形场 <a class="header-anchor" href="#环形场" aria-label="Permalink to &quot;环形场&quot;">​</a></h1><div class="epigraph"><p>EUV 投影在像面上给出的是一段窄弧，不是浸没机那条直狭缝。扫描把弧扫成矩形场；弧宽就是瞬时焦深和像差都还必须成立的那一条。</p><footer>—— 对照 Zeiss / ASML 对 EUV ring-field 扫描的公开光学布局；Bakshi 系统光学</footer></div><p><a href="/litho/reflectivity-mirror-count">上一课</a>用 \\(R^N\\) 卡住了镜数。缺口是场：全反射、离轴、环形视场（ring field）是少镜数下仍能控像差的经典解。光瞳里还剩多少填充，留给<a href="/litho/pupil-fill-ratio">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>镜数预算不允许再堆折射式那种多片补偿。EUV 投影用离轴非球面反射组，良好校正的瞬时视场自然落在以光轴为心的窄环上——像面上是一段弧形狭缝。DUV 浸没的直狭缝是折射物镜的远轴设计结果，不能照搬。若强行做大方场、多镜校正，透过率先死。</p><p>缺口是把「弧」写成扫描几何，而不是再乘一次 \\(R\\)。工件台沿扫描方向把弧扫过场高度，曝光场是矩形；弧的宽度（scan-cross 方向的瞬时场）受像差、多层角谱和焦深限制。High-NA 半场，是环形场在更大 NA 下的再切割，不是另一种物理。</p><p><span class="marginnote">环形场是瞬时像面形状。硅片上的曝光场仍是扫描出来的矩形（High-NA 上是半场矩形）。不要把 ring field 理解成芯片是弧形的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>照明把 IF 整形后，沿弧均匀照亮掩模上的共轭狭缝。狭缝宽度进入剂量：\\(D\\sim I\\cdot t_{\\mathrm{dwell}}\\)，扫速与弧宽一起定停留时间。均匀性要沿弧长做，沿扫描方向靠速度和脉冲积分。掩模侧主光线角沿弧变化，<a href="/litho/euv-oblique-shadow">斜入射阴影</a> 和 M3D 偏置随狭缝位置变，OPC 必须带狭缝坐标。</p><p><span class="marginnote">直觉类比：停留时间就像手机拍夜景——快门越短进光越少，想不糊（剂量够）就只能把灯（光源功率）开得更亮。弧宽、扫速、源功率被绑在同一辆车上，就是这个道理。</span></p><p>装调与热：弧上各点对应镜子上不同足迹，面形和 MSFR 的指纹会沿弧展开成 CD 图。收集镜径向污染不均，先表现为弧上照度不均。</p><h3 id="弧宽是剂量也是像差" tabindex="-1">弧宽是剂量也是像差 <a class="header-anchor" href="#弧宽是剂量也是像差" aria-label="Permalink to &quot;弧宽是剂量也是像差&quot;">​</a></h3><p>弧在扫描方向的宽度决定停留时间，也决定瞬时视场有多偏离设计环。加宽弧可以提高光子积分、放慢对源功率的苛求，像差和多层角谱会先越界。收窄弧则相反：像质好、产能要功率补。环形场宽度与 IF 瓦数是同一张表的两边，不能只在照明配方里偷偷加宽。</p>',13)),(i(),A(o,null,{default:e(()=>[s(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20OFF%5B%22%E7%A6%BB%E8%BD%B4%E5%8F%8D%E5%B0%84%E7%BB%84%22%5D%20--%3E%20ARC%5B%22%E5%83%8F%E9%9D%A2%E7%8E%AF%E5%BD%A2%E7%9E%AC%E6%97%B6%E5%9C%BA%22%5D%0A%20%20ARC%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%E6%88%90%E7%9F%A9%E5%BD%A2%E5%9C%BA%22%5D%0A%20%20N%5B%22%E5%B0%91%E9%95%9C%E6%95%B0%E9%A2%84%E7%AE%97%22%5D%20--%3E%20OFF%0A%20%20ARC%20--%3E%20CRA%5B%22%E6%B2%BF%E5%BC%A7%E4%B8%BB%E5%85%89%E7%BA%BF%E8%A7%92%E5%8F%98%E5%8C%96%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"环的半径和宽度来自像差平衡：某些慧差、像散在环上抵消或可容忍。离开设计环，波前迅速超标。这与同步辐射束线的环场光学同族，光刻把它做成扫描狭缝。波长短、公差紧，环更窄；产能就靠扫速和 IF 功率补——又回到功率路线。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"术语翻译：「像差平衡」是说设计者故意让几种成像缺陷（慧差、像散等）在某个曲面带上互相抵消。设计环就是抵消刚好成立的窄带；离开这条带，缺陷立刻露头——这就是狭缝必须贴着设计环扫的原因。")],-1)),(i(),A(o,null,{default:e(()=>[s(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20RING%5B%22%E8%AE%BE%E8%AE%A1%E7%8E%AF%E4%B8%8A%E7%9A%84%E5%83%8F%E5%B7%AE%E5%B9%B3%E8%A1%A1%22%5D%20--%3E%20LEAVE%5B%22%E7%8B%AD%E7%BC%9D%E5%81%8F%E7%A6%BB%E8%AE%BE%E8%AE%A1%E7%8E%AF%22%5D%0A%20%20LEAVE%20--%3E%20WF%5B%22%E6%B3%A2%E5%89%8D%E8%AF%AF%E5%B7%AE%E4%B8%8A%E5%8D%87%22%5D%0A%20%20WF%20--%3E%20CD%5B%22CD%20%E6%B2%BF%E5%BC%A7%E6%BC%82%E7%A7%BB%22%5D%0A%20%20NARROW%5B%22%E6%8A%8A%E7%8E%AF%E6%94%B6%E7%AA%84%E4%BF%9D%E5%83%8F%E8%B4%A8%22%5D%20--%3E%20DWELL%5B%22%E5%81%9C%E7%95%99%E6%97%B6%E9%97%B4%E5%8F%98%E7%9F%AD%22%5D%0A%20%20DWELL%20--%3E%20DOSE%5B%22%E5%89%82%E9%87%8F%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20DOSE%20--%3E%20PWR%5B%22%E5%8F%AA%E8%83%BD%E5%8A%A0%E5%85%89%E6%BA%90%E5%8A%9F%E7%8E%87%E8%A1%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>High-NA 变形光学在扫描和交扫方向用不同倍率，弧的共轭在掩模上变成「瘦高」的照明区。场切半是为了让镜子口径和 CRA 活在多层角窗里，环形场逻辑不变，只是环的可用长度被裁短。</p><p><span class="marginnote">常见误区：以为 High-NA 把场切半是「为了更精细成像」另起炉灶的新物理，其实只是把原来的环形视场再裁短一段——镜子口径和入射角仍要活在多层膜反射的角度窗口里，环的几何逻辑一点没变。</span></p><p><span class="marginnote">剂量传感器若只看弧的中点，边缘 CRA 和照度误差会被漏掉。沿弧采样是环形场的计量税。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把光瞳填充比写成 etendue 公式，下一课才把源尺寸与光瞳匹配。不重写工件台加速度。弧不是芯片形状：扫描才把瞬时环扫成矩形场（High-NA 上是半场）。出处：Zeiss/ASML ring-field 扫描布局；Bakshi；斜入射课的沿狭缝 CRA。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>少镜数全反射把瞬时场收成窄弧；扫描把弧sweep 成矩形曝光场。</li><li>沿弧的 CRA、照度和像差都是场相关量，OPC 不能当直狭缝。</li><li>下一课：弧上的照明在光瞳里填多少。</li><li>出处：Zeiss、ASML、Bakshi。</li></ul>',7))])}const _=n(p,[["render",h]]);export{c as __pageData,_ as default};
